1	/**
2	 * Artifact Generator
3	 * 
4	 * Generates proof artifacts for every agent run:
5	 * - agent_run_report.json + .md
6	 * - gate_report.json + .md
7	 * - decision_trace.json
8	 * 
9	 * These artifacts are attached to PRs and stored for audit.
10	 */
11	
12	import * as crypto from 'crypto';
13	import { storagePut } from '../storage';
14	import { generalLog } from '../_core/logger';
15	
16	// ============================================================================
17	// TYPES
18	// ============================================================================
19	
20	export interface AgentRunReport {
21	  runId: string;
22	  surface: string;
23	  repo: string;
24	  prNumber: number;
25	  triggeredBy: string;
26	  triggerType: 'webhook' | 'command' | 'scheduled' | 'manual';
27	  startedAt: string;
28	  finishedAt: string | null;
29	  status: 'pending' | 'running' | 'passed' | 'blocked' | 'failed' | 'cancelled';
30	  iterations: number;
31	  patchesApplied: number;
32	  tokensUsed: number;
33	  proofBlockId: string;
34	  previousRunHash: string;
35	  runHash: string;
36	  gateDecision: GateDecision;
37	  patches: PatchRecord[];
38	  metadata: Record<string, unknown>;
39	}
40	
41	export interface GateDecision {
42	  decision: 'pass' | 'block' | 'warn';
43	  score: number;
44	  threshold: number;
45	  rubricScores: RubricScore[];
46	  issues: Issue[];
47	  recommendations: string[];
48	  businessTruthCheck: BusinessTruthCheck;
49	  identityCheck: IdentityCheck;
50	}
51	
52	export interface RubricScore {
53	  dimension: string;
54	  score: number;
55	  weight: number;
56	  feedback: string;
57	}
58	
59	export interface Issue {
60	  severity: 'critical' | 'high' | 'medium' | 'low';
61	  category: string;
62	  description: string;
63	  location?: string;
64	  suggestedFix?: string;
65	}
66	
67	export interface BusinessTruthCheck {
68	  passed: boolean;
69	  claimsValidated: number;
70	  claimsRejected: number;
71	  forbiddenPatternsFound: string[];
72	  requiredDisclosuresPresent: boolean;
73	}
74	
75	export interface IdentityCheck {
76	  passed: boolean;
77	  divergenceScore: number;
78	  canonicalAlignment: number;
79	  forbiddenIdentitiesFound: string[];
80	  buyerAlignmentScore: number;
81	}
82	
83	export interface PatchRecord {
84	  patchId: string;
85	  iteration: number;
86	  filePath: string;
87	  changeType: 'add' | 'modify' | 'delete';
88	  before: string;
89	  after: string;
90	  reason: string;
91	  appliedAt: string;
92	}
93	
94	export interface DecisionTrace {
95	  traceId: string;
96	  runId: string;
97	  spans: TraceSpan[];
98	  startTime: string;
99	  endTime: string | null;
100	  totalDuration: number | null;
101	}
102	
103	export interface TraceSpan {
104	  spanId: string;
105	  parentSpanId: string | null;
106	  operation: string;
107	  startTime: string;
108	  endTime: string;
109	  duration: number;
110	  status: 'ok' | 'error';
111	  attributes: Record<string, unknown>;
112	  events: SpanEvent[];
113	}
114	
115	export interface SpanEvent {
116	  name: string;
117	  timestamp: string;
118	  attributes: Record<string, unknown>;
119	}
120	
121	export interface GateReport {
122	  reportId: string;
123	  runId: string;
124	  generatedAt: string;
125	  summary: GateReportSummary;
126	  details: GateReportDetails;
127	  recommendations: GateReportRecommendation[];
128	}
129	
130	export interface GateReportSummary {
131	  decision: 'pass' | 'block' | 'warn';
132	  score: number;
133	  threshold: number;
134	  issueCount: {
135	    critical: number;
136	    high: number;
137	    medium: number;
138	    low: number;
139	  };
140	  iterationsRequired: number;
141	  patchesApplied: number;
142	}
143	
144	export interface GateReportDetails {
145	  rubricBreakdown: RubricScore[];
146	  businessTruth: BusinessTruthCheck;
147	  identity: IdentityCheck;
148	  topIssues: Issue[];
149	}
150	
151	export interface GateReportRecommendation {
152	  priority: 'high' | 'medium' | 'low';
153	  category: string;
154	  recommendation: string;
155	  effort: 'low' | 'medium' | 'high';
156	}
157	
158	// ============================================================================
159	// ARTIFACT GENERATOR
160	// ============================================================================
161	
162	export class ArtifactGenerator {
163	  private basePath: string;
164	
165	  constructor(basePath: string = '/reports') {
166	    this.basePath = basePath;
167	  }
168	
169	  /**
170	   * Generate all artifacts for an agent run
171	   */
172	  async generateAllArtifacts(
173	    runReport: AgentRunReport,
174	    decisionTrace: DecisionTrace
175	  ): Promise<GeneratedArtifacts> {
176	    const gateReport = this.buildGateReport(runReport);
177	    
178	    // Generate JSON artifacts
179	    const runReportJson = JSON.stringify(runReport, null, 2);
180	    const gateReportJson = JSON.stringify(gateReport, null, 2);
181	    const decisionTraceJson = JSON.stringify(decisionTrace, null, 2);
182	
183	    // Generate Markdown artifacts
184	    const runReportMd = this.generateRunReportMarkdown(runReport);
185	    const gateReportMd = this.generateGateReportMarkdown(gateReport);
186	
187	    // Build artifact paths
188	    const artifactPath = `${this.basePath}/${runReport.repo}/${runReport.prNumber}/${runReport.runId}`;
189	
190	    // Store artifacts
191	    const artifacts: GeneratedArtifacts = {
192	      runReportJson: {
193	        path: `${artifactPath}/agent_run_report.json`,
194	        content: runReportJson,
195	        url: null,
196	      },
197	      runReportMd: {
198	        path: `${artifactPath}/agent_run_report.md`,
199	        content: runReportMd,
200	        url: null,
201	      },
202	      gateReportJson: {
203	        path: `${artifactPath}/gate_report.json`,
204	        content: gateReportJson,
205	        url: null,
206	      },
207	      gateReportMd: {
208	        path: `${artifactPath}/gate_report.md`,
209	        content: gateReportMd,
210	        url: null,
211	      },
212	      decisionTraceJson: {
213	        path: `${artifactPath}/decision_trace.json`,
214	        content: decisionTraceJson,
215	        url: null,
216	      },
217	    };
218	
219	    // Upload to S3
220	    try {
221	      for (const [key, artifact] of Object.entries(artifacts)) {
222	        const contentType = artifact.path.endsWith('.json') 
223	          ? 'application/json' 
224	          : 'text/markdown';
225	        
226	        const { url } = await storagePut(
227	          artifact.path,
228	          artifact.content,
229	          contentType
230	        );
231	        artifact.url = url;
232	      }
233	    } catch (error) {
234	      generalLog.warn('[ArtifactGenerator] Failed to upload to S3:', error);
235	      // Continue without S3 URLs - artifacts are still generated
236	    }
237	
238	    return artifacts;
239	  }
240	
241	  /**
242	   * Build gate report from run report
243	   */
244	  private buildGateReport(runReport: AgentRunReport): GateReport {
245	    const gd = runReport.gateDecision;
246	    
247	    return {
248	      reportId: `gr_${crypto.randomBytes(8).toString('hex')}`,
249	      runId: runReport.runId,
250	      generatedAt: new Date().toISOString(),
251	      summary: {
252	        decision: gd.decision,
253	        score: gd.score,
254	        threshold: gd.threshold,
255	        issueCount: {
256	          critical: (gd.issues || []).filter(i => i.severity === 'critical').length,
257	          high: (gd.issues || []).filter(i => i.severity === 'high').length,
258	          medium: (gd.issues || []).filter(i => i.severity === 'medium').length,
259	          low: (gd.issues || []).filter(i => i.severity === 'low').length,
260	        },
261	        iterationsRequired: runReport.iterations,
262	        patchesApplied: runReport.patchesApplied,
263	      },
264	      details: {
265	        rubricBreakdown: gd.rubricScores,
266	        businessTruth: gd.businessTruthCheck,
267	        identity: gd.identityCheck,
268	        topIssues: (gd.issues || []).slice(0, 5),
269	      },
270	      recommendations: this.generateRecommendations(gd),
271	    };
272	  }
273	
274	  /**
275	   * Generate recommendations from gate decision
276	   */
277	  private generateRecommendations(gd: GateDecision): GateReportRecommendation[] {
278	    const recommendations: GateReportRecommendation[] = [];
279	
280	    // Add recommendations based on issues
281	    for (const issue of (gd.issues || []).filter(i => i.severity === 'critical' || i.severity === 'high')) {
282	      recommendations.push({
283	        priority: issue.severity === 'critical' ? 'high' : 'medium',
284	        category: issue.category,
285	        recommendation: issue.suggestedFix || `Address ${issue.category}: ${issue.description}`,
286	        effort: issue.severity === 'critical' ? 'high' : 'medium',
287	      });
288	    }
289	
290	    // Add recommendations based on business truth
291	    if (!gd.businessTruthCheck.passed) {
292	      if (gd.businessTruthCheck.forbiddenPatternsFound?.length > 0) {
293	        recommendations.push({
294	          priority: 'high',
295	          category: 'business_truth',
296	          recommendation: `Remove forbidden patterns: ${(gd.businessTruthCheck.forbiddenPatternsFound || []).join(', ')}`,
297	          effort: 'medium',
298	        });
299	      }
300	      if (!gd.businessTruthCheck.requiredDisclosuresPresent) {
301	        recommendations.push({
302	          priority: 'high',
303	          category: 'business_truth',
304	          recommendation: 'Add required disclosures for claims',
305	          effort: 'low',
306	        });
307	      }
308	    }
309	
310	    // Add recommendations based on identity
311	    if (!gd.identityCheck.passed) {
312	      if (gd.identityCheck.divergenceScore > 30) {
313	        recommendations.push({
314	          priority: 'high',
315	          category: 'identity',
316	          recommendation: `Reduce identity divergence (current: ${gd.identityCheck.divergenceScore}%, target: <30%)`,
317	          effort: 'high',
318	        });
319	      }
320	      if (gd.identityCheck.forbiddenIdentitiesFound?.length > 0) {
321	        recommendations.push({
322	          priority: 'high',
323	          category: 'identity',
324	          recommendation: `Remove forbidden identity patterns: ${(gd.identityCheck.forbiddenIdentitiesFound || []).join(', ')}`,
325	          effort: 'medium',
326	        });
327	      }
328	    }
329	
330	    // Add general recommendations
331	    for (const rec of gd.recommendations) {
332	      recommendations.push({
333	        priority: 'low',
334	        category: 'general',
335	        recommendation: rec,
336	        effort: 'low',
337	      });
338	    }
339	
340	    return recommendations;
341	  }
342	
343	  /**
344	   * Generate run report markdown
345	   */
346	  private generateRunReportMarkdown(report: AgentRunReport): string {
347	    const statusEmoji = {
348	      pending: '⏳',
349	      running: '🔄',
350	      passed: '✅',
351	      blocked: '🚫',
352	      failed: '❌',
353	      cancelled: '⏹️',
354	    };
355	
356	    let md = `# Agent Run Report\n\n`;
357	    md += `**Run ID:** \`${report.runId}\`\n`;
358	    md += `**Status:** ${statusEmoji[report.status]} ${report.status.toUpperCase()}\n`;
359	    md += `**Surface:** ${report.surface}\n`;
360	    md += `**Repository:** ${report.repo}\n`;
361	    md += `**PR:** #${report.prNumber}\n\n`;
362	
363	    md += `## Timing\n\n`;
364	    md += `| Metric | Value |\n`;
365	    md += `|--------|-------|\n`;
366	    md += `| Started | ${report.startedAt} |\n`;
367	    md += `| Finished | ${report.finishedAt || 'In progress'} |\n`;
368	    md += `| Iterations | ${report.iterations} |\n`;
369	    md += `| Patches Applied | ${report.patchesApplied} |\n`;
370	    md += `| Tokens Used | ${report.tokensUsed.toLocaleString()} |\n\n`;
371	
372	    md += `## Gate Decision\n\n`;
373	    const gd = report.gateDecision;
374	    md += `**Decision:** ${gd.decision.toUpperCase()}\n`;
375	    md += `**Score:** ${gd.score}/100 (threshold: ${gd.threshold})\n\n`;
376	
377	    if (gd.rubricScores.length > 0) {
378	      md += `### Rubric Scores\n\n`;
379	      md += `| Dimension | Score | Weight | Feedback |\n`;
380	      md += `|-----------|-------|--------|----------|\n`;
381	      for (const rs of gd.rubricScores) {
382	        md += `| ${rs.dimension} | ${rs.score} | ${rs.weight} | ${rs.feedback} |\n`;
383	      }
384	      md += `\n`;
385	    }
386	
387	    if (gd.issues.length > 0) {
388	      md += `### Issues Found\n\n`;
389	      for (const issue of gd.issues) {
390	        const severityEmoji = {
391	          critical: '🔴',
392	          high: '🟠',
393	          medium: '🟡',
394	          low: '🟢',
395	        };
396	        md += `- ${severityEmoji[issue.severity]} **${issue.severity.toUpperCase()}** [${issue.category}]: ${issue.description}\n`;
397	        if (issue.suggestedFix) {
398	          md += `  - *Suggested fix:* ${issue.suggestedFix}\n`;
399	        }
400	      }
401	      md += `\n`;
402	    }
403	
404	    md += `## Business Truth Check\n\n`;
405	    const bt = gd.businessTruthCheck;
406	    md += `- **Passed:** ${bt.passed ? '✅ Yes' : '❌ No'}\n`;
407	    md += `- **Claims Validated:** ${bt.claimsValidated}\n`;
408	    md += `- **Claims Rejected:** ${bt.claimsRejected}\n`;
409	    md += `- **Required Disclosures:** ${bt.requiredDisclosuresPresent ? '✅ Present' : '❌ Missing'}\n`;
410	    if (bt.forbiddenPatternsFound?.length > 0) {
411	      md += `- **Forbidden Patterns:** ${(bt.forbiddenPatternsFound || []).join(', ')}\n`;
412	    }
413	    md += `\n`;
414	
415	    md += `## Identity Check\n\n`;
416	    const ic = gd.identityCheck;
417	    md += `- **Passed:** ${ic.passed ? '✅ Yes' : '❌ No'}\n`;
418	    md += `- **Divergence Score:** ${ic.divergenceScore}%\n`;
419	    md += `- **Canonical Alignment:** ${ic.canonicalAlignment}%\n`;
420	    md += `- **Buyer Alignment:** ${ic.buyerAlignmentScore}%\n`;
421	    if (ic.forbiddenIdentitiesFound?.length > 0) {
422	      md += `- **Forbidden Identities:** ${(ic.forbiddenIdentitiesFound || []).join(', ')}\n`;
423	    }
424	    md += `\n`;
425	
426	    if (report.patches.length > 0) {
427	      md += `## Patches Applied\n\n`;
428	      for (const patch of report.patches) {
429	        md += `### Patch ${patch.patchId}\n\n`;
430	        md += `- **File:** \`${patch.filePath}\`\n`;
431	        md += `- **Type:** ${patch.changeType}\n`;
432	        md += `- **Reason:** ${patch.reason}\n`;
433	        md += `- **Applied:** ${patch.appliedAt}\n\n`;
434	      }
435	    }
436	
437	    md += `## Provenance\n\n`;
438	    md += `| Field | Value |\n`;
439	    md += `|-------|-------|\n`;
440	    md += `| Proof Block ID | \`${report.proofBlockId}\` |\n`;
441	    md += `| Previous Run Hash | \`${report.previousRunHash}\` |\n`;
442	    md += `| Run Hash | \`${report.runHash}\` |\n`;
443	    md += `| Triggered By | ${report.triggeredBy} |\n`;
444	    md += `| Trigger Type | ${report.triggerType} |\n`;
445	
446	    return md;
447	  }
448	
449	  /**
450	   * Generate gate report markdown
451	   */
452	  private generateGateReportMarkdown(report: GateReport): string {
453	    const decisionEmoji = {
454	      pass: '✅',
455	      block: '🚫',
456	      warn: '⚠️',
457	    };
458	
459	    let md = `# Gate Report\n\n`;
460	    md += `**Report ID:** \`${report.reportId}\`\n`;
