    artifacts.push(
      { name: 'agent_run_report.json', url: generatedArtifacts.runReportJson.url || `/artifacts/${runId}/agent_run_report.json`, type: 'json' },
      { name: 'gate_report.json', url: generatedArtifacts.gateReportJson.url || `/artifacts/${runId}/gate_report.json`, type: 'json' },
      { name: 'decision_trace.json', url: generatedArtifacts.decisionTraceJson.url || `/artifacts/${runId}/decision_trace.json`, type: 'json' }
    );

    // SiteGraph summary - save to file system
    // Determine status based on score
    const healthStatus = auditResult.score >= 80 ? 'healthy' : auditResult.score >= 50 ? 'warning' : 'critical';
    const hasIssues = (auditResult.issues || []).length > 0;

    const siteGraphSummary = {
      summaryId: `sg_${runId}`,
      runId,
      repo: 'gravito/website',
