  /**
   * Format audit result as PR comment
   */
  private formatAuditComment(
    runId: string,
    auditResult: any,
    artifacts: Array<{ name: string; url: string; type: string }>
  ): string {
    const status = auditResult.passed ? '✅ PASS' : '❌ FAIL';
    const issueList = (auditResult.issues || []).length > 0
      ? (auditResult.issues || []).map((i: any) => `- **${i.type}**: ${i.message}`).join('\n')
      : 'No issues found';

    return `## 🤖 Gravito Audit Results

**Run ID:** \`${runId}\`
**Status:** ${status}
**Score:** ${auditResult.score}/100

### Issues
${issueList}

### Artifacts
${(artifacts || []).map(a => `- [${a.name}](${a.url})`).join('\n')}

---
*Powered by Gravito - The release gate for AI-generated content*`;
  }

  /**
   * Post comment to PR
   */
  async postComment(context: PRContext, body: string): Promise<void> {
    // Log the comment for debugging
    securityLog.info({ repo: context.repo, prNumber: context.prNumber }, '[GitHubApp] Posting comment');

    // If no installation ID, we can't post to GitHub
    if (!context.installationId) {
      securityLog.warn({ repo: context.repo, prNumber: context.prNumber }, '[GitHubApp] No installation ID, cannot post comment to GitHub');
      return;
    }

    try {
      // Get installation access token
      const token = await this.getInstallationToken(context.installationId);

      // Post comment via GitHub API
      const [owner, repo] = context.repo.split('/');
      const response = await fetch(
        `https://api.github.com/repos/${owner}/${repo}/issues/${context.prNumber}/comments`,
        {
          method: 'POST',
          headers: {
            'Authorization': `Bearer ${token}`,
            'Accept': 'application/vnd.github+json',
            'X-GitHub-Api-Version': '2022-11-28',
            'Content-Type': 'application/json',
          },
          body: JSON.stringify({ body }),
        }
      );

      if (!response.ok) {
        const errorText = await response.text();
        securityLog.error({ status: response.status, errorText }, '[GitHubApp] Failed to post comment');
        throw new Error(`Failed to post comment: ${response.status}`);
      }

      const data = await response.json() as { id: number; html_url: string };
      securityLog.info({ commentId: data.id, url: data.html_url }, '[GitHubApp] Posted comment');
    } catch (error) {
      securityLog.error({ err: error instanceof Error ? error : new Error(String(error)) }, '[GitHubApp] Error posting comment');
      // Don't throw - we still want the run to complete even if comment fails
    }
  }

  /**
   * Update PR status check
   */
  async updateStatus(
    context: PRContext,
    state: 'pending' | 'success' | 'failure',
    description: string
  ): Promise<void> {
    // In production, would call GitHub API
    securityLog.info({ repo: context.repo, prNumber: context.prNumber, state, description }, '[GitHubApp] Status update');
  }
}

/**
 * Create Express router for GitHub webhook endpoint
 */
export function createGitHubWebhookRouter(app: GitHubApp) {
  return {
    path: '/api/github/webhook',
    handler: async (req: any, res: any) => {
      const signature = req.headers['x-hub-signature-256'];
      const payload = JSON.stringify(req.body);

      // Verify signature
      if (!app.verifyWebhookSignature(payload, signature)) {
        return res.status(401).json({ error: 'Invalid signature' });
      }

      // Process event
      const event = req.body as GitHubWebhookEvent;
      const result = await app.processWebhookEvent(event);

      return res.json(result);
    },
  };
}

// Export for testing
export { GitHubApp as default };

