/**
 * GitHub App Integration for Real Webhook Events
 * 
 * This module handles real GitHub webhook events and executes
 * the Gravito PR Agent workflow on actual repositories.
 * 
 * Uses Claude+OpenAI+Gravito for:
 * - Claude: Generates patches and explanations
 * - OpenAI: Cross-check logging (optional)
 * - Gravito: Gate verification (never same model as generator)
 */

import crypto from 'crypto';
import { securityLog } from '../_core/logger';
import { PRCommandHandler, ParsedCommand, CommandType, PermissionConfig, RateLimitConfig } from './pr-commands';

// Gravito command type for webhook handling
export interface GravitoCommand {
  type: CommandType;
  args: string[];
  raw: string;
}
import { GitOperations } from './git-operations';
import { ArtifactGenerator, RubricScore } from './artifact-generator';
import { SiteGraphArtifactGenerator } from './sitegraph-artifact';
import { governedGenerate } from '../governance/governed-generate';
import { GitHubContentFetcher, ArtifactBundle, formatBundleForLLM, FetchResult } from './github-content-fetcher';
import { validateMultiModel, normalizeAuditOutput, getMultiModelValidationSummary, AuditOutput } from './validation';
import { checkIdempotency, createAuditRun, markAuditRunning, completeAuditRun, failAuditRun, formatCachedResultComment, PROMPT_VERSION, POLICY_VERSION } from './idempotency';
import { checkRateLimit, formatRateLimitComment } from './rate-limiter';
import { emptyArray, shapeCast} from '../../shared/type-bridge';
import { MODELS } from "../_core/models";

// GitHub webhook event types
export interface GitHubWebhookEvent {
  action: string;
  repository: {
    full_name: string;
    clone_url: string;
    default_branch: string;
  };
  pull_request?: {
    number: number;
    title: string;
    body: string;
    head: {
      ref: string;
      sha: string;
    };
    base: {
      ref: string;
    };
    user: {
      login: string;
    };
    html_url: string;
  };
  // For issue_comment events, the issue object contains PR info
  issue?: {
    number: number;
    title: string;
    body?: string;
    user: {
      login: string;
    };
    pull_request?: {
      url: string;
    };
  };
  comment?: {
    id: number;
    body: string;
    user: {
      login: string;
    };
  };
  sender: {
    login: string;
  };
  installation?: {
    id: number;
  };
}

export interface GitHubAppConfig {
  appId: string;
  privateKey: string;
  webhookSecret: string;
  clientId?: string;
  clientSecret?: string;
}

export interface PRContext {
  repo: string;
  prNumber: number;
  branch: string;
  baseBranch: string;
  author: string;
  title: string;
  installationId?: number;
  headSha?: string; // HEAD SHA for idempotency
  triggeredBy?: string; // User who triggered the command
}

export interface GitHubAPIResponse {
  success: boolean;
  data?: any;
  error?: string;
}

/**
 * GitHub App Integration Class
 * 
 * Handles webhook verification, event processing, and GitHub API calls
 */
export class GitHubApp {
  private config: GitHubAppConfig & { adminAllowlist?: string[] };
  private commandHandler: PRCommandHandler;
  private gitOps: GitOperations;
  private artifactGen: ArtifactGenerator;
  private siteGraphGen: SiteGraphArtifactGenerator;
  private contentFetcher: GitHubContentFetcher;
  private accessTokens: Map<number, { token: string; expiresAt: Date }> = new Map();

  constructor(config: GitHubAppConfig) {
    // Convert escaped newlines in private key to actual newlines
    if (config.privateKey) {
      config.privateKey = config.privateKey.replace(/\\n/g, '\n');
    }
    this.config = config;
    this.commandHandler = new PRCommandHandler(
      {
        repoAllowlist: [], // Will be populated from config
        adminAllowlist: [],
        forkAllowlist: [],
        blockedPages: ['auth', 'payments', 'security', 'legal'],
      },
      {
        maxRunsPerPRPerHour: 3,
        maxRunsPerRepoPerDay: 50,
        maxTokensPerDay: 1000000,
      }
    );
    this.gitOps = new GitOperations();
    this.artifactGen = new ArtifactGenerator();
    this.siteGraphGen = new SiteGraphArtifactGenerator();
    this.contentFetcher = new GitHubContentFetcher((installationId) => this.getInstallationToken(installationId));
  }

  /**
   * Verify webhook signature using HMAC-SHA256
   */
  verifyWebhookSignature(payload: string, signature: string): boolean {
    if (!signature) return false;

    const expectedSignature = 'sha256=' + crypto
      .createHmac('sha256', this.config.webhookSecret)
      .update(payload)
      .digest('hex');

    try {
      return crypto.timingSafeEqual(
        Buffer.from(signature),
        Buffer.from(expectedSignature)
      );
    } catch {
      return false;
    }
  }

  /**
   * Get installation access token for GitHub API calls
   */
  async getInstallationToken(installationId: number): Promise<string> {
    // Check cache
    const cached = this.accessTokens.get(installationId);
    if (cached && cached.expiresAt > new Date()) {
      return cached.token;
    }

    // Generate JWT for app authentication
    const now = Math.floor(Date.now() / 1000);
    const jwt = this.generateJWT(now);

    try {
      // Exchange JWT for installation token via GitHub API
      const response = await fetch(
        `https://api.github.com/app/installations/${installationId}/access_tokens`,
        {
          method: 'POST',
          headers: {
            'Authorization': `Bearer ${jwt}`,
            'Accept': 'application/vnd.github+json',
            'X-GitHub-Api-Version': '2022-11-28',
          },
        }
      );

      if (!response.ok) {
        const errorText = await response.text();
        securityLog.error({ status: response.status, errorText }, '[GitHubApp] Failed to get installation token');
        throw new Error(`Failed to get installation token: ${response.status}`);
      }

      const data = await response.json() as { token: string; expires_at: string };

      this.accessTokens.set(installationId, {
        token: data.token,
        expiresAt: new Date(data.expires_at),
      });

      securityLog.info({ installationId }, '[GitHubApp] Got installation token');
      return data.token;
    } catch (error) {
      securityLog.error({ err: error instanceof Error ? error : new Error(String(error)), installationId }, '[GitHubApp] Error getting installation token');
      throw error instanceof Error ? error : new Error(String(error));
    }
  }

  /**
   * Generate JWT for GitHub App authentication
   */
  private generateJWT(now: number): string {
    // JWT header and payload
    const header = { alg: 'RS256', typ: 'JWT' };
    const payload = {
      iat: now - 60,
      exp: now + 600,
      iss: this.config.appId,
    };

    const encodedHeader = Buffer.from(JSON.stringify(header)).toString('base64url');
    const encodedPayload = Buffer.from(JSON.stringify(payload)).toString('base64url');

    if (!this.config.privateKey?.trim()) {
      throw new Error('[GitHubApp] GITHUB_APP_PRIVATE_KEY (or config.privateKey) is required to sign installation JWTs');
    }
    try {
      const sign = crypto.createSign('RSA-SHA256');
      sign.update(`${encodedHeader}.${encodedPayload}`);
      const signature = sign.sign(this.config.privateKey, 'base64url');
      return `${encodedHeader}.${encodedPayload}.${signature}`;
    } catch (error) {
      securityLog.error({ err: error instanceof Error ? error : new Error(String(error)) }, '[GitHubApp] Error signing JWT');
      throw error instanceof Error ? error : new Error(String(error));
    }
  }

  /**
   * Process incoming webhook event
   */
  async processWebhookEvent(event: GitHubWebhookEvent): Promise<{
    processed: boolean;
    action?: string;
    result?: any;
    error?: string;
  }> {
    // Handle PR comment events (command triggers)
    // For issue_comment events on PRs, the PR info is in the `issue` object with a `pull_request` field
    const isCommentOnPR = event.action === 'created' && event.comment && 
      (event.pull_request || event.issue?.pull_request);

    if (isCommentOnPR) {
      return this.handlePRComment(event);
    }

    // Handle PR opened/synchronized events
    if (event.pull_request && ['opened', 'synchronize'].includes(event.action)) {
      return this.handlePREvent(event);
    }

    return { processed: false, action: 'ignored' };
  }

  /**
   * Handle PR comment containing /gravito command
   * 
   * Note: For issue_comment events on PRs, GitHub sends the PR info in the `issue` object,
   * not the `pull_request` object. The full PR details need to be fetched from the API.
   */
  private async handlePRComment(event: GitHubWebhookEvent): Promise<{
    processed: boolean;
    action?: string;
    result?: any;
    error?: string;
  }> {
    const comment = event.comment!;
    const repo = event.repository.full_name;

    // Check if comment contains /gravito command
    if (!comment.body.includes('/gravito')) {
      return { processed: false, action: 'no_command' };
    }

    // For issue_comment events, PR info is in the issue object
    // The pull_request field exists only if the issue is a PR
    const pr = event.pull_request;
    const issue = event.issue;

    // Determine PR number from either source
    const prNumber = pr?.number ?? issue?.number;
    if (!prNumber) {
      return { processed: false, action: 'no_pr_context', error: 'Could not determine PR number' };
    }

    // Check if this is actually a PR (not just an issue)
    if (!pr && !issue?.pull_request) {
      return { processed: false, action: 'not_a_pr', error: 'Comment is on an issue, not a PR' };
    }

    // Parse command
    const command = this.commandHandler.parseCommand(
      comment.body,
      comment.id.toString(),
      comment.user.login,
      repo,
      prNumber
    );
    if (!command) {
      return { processed: false, action: 'invalid_command' };
    }

    // Build PR context with available data
    // For issue_comment events, we may not have full PR details
    const context: PRContext = {
      repo,
      prNumber,
      // Use available data or defaults
      branch: pr?.head?.ref ?? issue?.title?.split(' ')[0] ?? 'unknown',
      baseBranch: pr?.base?.ref ?? event.repository.default_branch ?? 'main',
      author: pr?.user?.login ?? issue?.user?.login ?? event.sender.login,
      title: pr?.title ?? issue?.title ?? `PR #${prNumber}`,
      installationId: event.installation?.id,
      headSha: pr?.head?.sha,
      triggeredBy: comment.user.login,
    };

    // Execute command
    try {
      const result = await this.executeCommand(command, context, comment.user.login);
      return {
        processed: true,
        action: command.type,
        result,
      };
    } catch (error) {
      securityLog.error({ err: error instanceof Error ? error : new Error(String(error)), commandType: command.type }, '[GitHubApp] Error executing command');
      return {
        processed: false,
        action: command.type,
        error: error instanceof Error ? error.message : 'Unknown error',
      };
    }
  }

  /**
   * Handle PR opened/synchronized event
   */
  private async handlePREvent(event: GitHubWebhookEvent): Promise<{
    processed: boolean;
    action?: string;
    result?: any;
    error?: string;
  }> {
    const pr = event.pull_request!;
    const repo = event.repository.full_name;

    // Build context
    const context: PRContext = {
      repo,
      prNumber: pr.number,
      branch: pr.head.ref,
      baseBranch: pr.base.ref,
      author: pr.user.login,
      title: pr.title,
      installationId: event.installation?.id,
      headSha: pr.head.sha,
      triggeredBy: pr.user.login,
    };

    // Auto-audit on PR open (if enabled)
    // For now, just acknowledge the event
    return {
      processed: true,
      action: 'pr_' + event.action,
      result: {
        message: `PR #${pr.number} ${event.action}`,
        context,
      },
    };
  }

  /**
   * Execute a Gravito command
   */
  async executeCommand(
    command: GravitoCommand,
    context: PRContext,
    executor: string
  ): Promise<any> {
    // Generate run ID
    const runId = this.commandHandler.generateRunId('website');

    // Post acknowledgment comment
    await this.postComment(context, `🤖 Starting \`${runId}\`\n\nCommand: \`/gravito ${command.type}\`\nExecutor: @${executor}`);

    switch (command.type) {
      case 'run':
        return this.executeRun(context, runId);
      case 'fix':
        return this.executeFix(context, runId);
      case 'explain':
        return this.executeExplain(context, runId, command.args);
      case 'status':
        return this.executeStatus(context, runId);
      case 'rollback':
        return this.executeRollback(context, runId, command.args);
      case 'autopilot':
        return this.executeAutopilot(context, runId, command.args, executor);
      default:
        throw new Error(`Unknown command: ${command.type}`);
    }
  }

  /**
   * Execute /gravito run - full audit without changes
   */
  private async executeRun(context: PRContext, runId: string): Promise<any> {
    const startTime = Date.now();

    try {
      securityLog.info({ runId }, '[GitHubApp] executeRun started');

      // Get the PR SHA for idempotency
      const prSha = context.headSha || 'unknown';

      // Extract org from repo (e.g., "owner/repo" -> "owner")
      const org = context.repo.split('/')[0];

      // Check rate limits before proceeding
      const rateLimitStatus = await checkRateLimit({ repo: context.repo, org });
      if (!rateLimitStatus.allowed) {
        securityLog.info({ repo: context.repo, reason: rateLimitStatus.reason }, '[GitHubApp] Rate limit exceeded');

        // Post rate limit comment
        await this.postComment(context, formatRateLimitComment(rateLimitStatus, runId));

        return {
          runId,
          status: 'rate_limited',
          reason: rateLimitStatus.reason,
          retryAfter: rateLimitStatus.retryAfter,
        };
      }

      // Check idempotency - return cached result if same PR state already audited
      const idempotencyCheck = await checkIdempotency({
        repo: context.repo,
        prNumber: context.prNumber,
        prSha,
      });

      if (idempotencyCheck.cached && idempotencyCheck.existingRun) {
        const cachedRun = idempotencyCheck.existingRun;
        securityLog.info({ cachedRunId: cachedRun.runId }, '[GitHubApp] Returning cached result');

        // Post cached result comment
        await this.postComment(context, formatCachedResultComment(cachedRun));

        return {
          runId: cachedRun.runId,
          status: cachedRun.passed ? 'pass' : 'fail',
          score: cachedRun.score,
          cached: true,
          originalRunId: cachedRun.runId,
        };
      }

      // Create new audit run record
      let auditRun;
      try {
        auditRun = await createAuditRun({
          repo: context.repo,
          prNumber: context.prNumber,
          prSha,
          runId,
          triggeredBy: context.triggeredBy || 'unknown',
          triggerType: 'comment',
          installationId: context.installationId,
          primaryModel: MODELS.generation,
          primaryProvider: 'anthropic',
        });
        await markAuditRunning(runId);
      } catch (dbError) {
        securityLog.warn({ err: dbError instanceof Error ? dbError : new Error(String(dbError)) }, '[GitHubApp] Failed to create audit run record');
        // Continue without DB tracking
      }

      // Clone repo and checkout PR branch
      const workDir = `/tmp/gravito/${runId}`;

      // Run audit using Claude for analysis
      securityLog.info({ runId }, '[GitHubApp] Running audit');
      const auditResult = await this.runAudit(context, workDir, runId);
      securityLog.info({ runId, score: auditResult.score, passed: auditResult.passed }, '[GitHubApp] Audit completed');

      // Generate artifacts
      securityLog.info({ runId }, '[GitHubApp] Generating artifacts');
      const artifacts = await this.generateArtifacts(runId, auditResult, []);
      securityLog.info({ runId, count: artifacts?.length || 0 }, '[GitHubApp] Artifacts generated');

      // Post results
      securityLog.info({ runId }, '[GitHubApp] Posting comment');
      await this.postComment(context, this.formatAuditComment(runId, auditResult, artifacts));
      securityLog.info({ runId }, '[GitHubApp] Comment posted successfully');

      // Complete the audit run record
      const durationMs = Date.now() - startTime;
      try {
        await completeAuditRun(runId, {
          score: auditResult.score,
          passed: auditResult.passed,
          issues: auditResult.issues || [],
          filesAnalyzed: auditResult.artifactBundle?.files.map(f => f.path) || [],
          durationMs,
          markdownSummary: this.formatAuditComment(runId, auditResult, artifacts),
          fullResult: auditResult,
        });
        securityLog.info({ runId }, '[GitHubApp] Audit run record completed');
      } catch (dbError) {
        securityLog.warn({ err: dbError instanceof Error ? dbError : new Error(String(dbError)), runId }, '[GitHubApp] Failed to complete audit run record');
      }

      return {
        runId,
        status: auditResult.passed ? 'pass' : 'fail',
        score: auditResult.score,
        artifacts,
        durationMs,
      };
    } catch (error) {
      securityLog.error({ err: error instanceof Error ? error : new Error(String(error)), runId }, '[GitHubApp] executeRun error');
      // Stack trace included in the err object above

      // Mark the audit run as failed
      try {
        await failAuditRun(
          runId,
          error instanceof Error ? error.name : 'UNKNOWN_ERROR',
          error instanceof Error ? error.message : String(error)
        );
      } catch (dbError) {
        securityLog.warn({ err: dbError instanceof Error ? dbError : new Error(String(dbError)), runId }, '[GitHubApp] Failed to mark audit run as failed');
      }

      throw error;
    }
  }

  /**
   * Execute /gravito fix - audit, patch, and iterate until PASS
   */
  private async executeFix(context: PRContext, runId: string): Promise<any> {
    const workDir = `/tmp/gravito/${runId}`;
    const maxIterations = 3;
    const commits: string[] = [];
    let iteration = 0;
    let currentScore = 0;
    let passed = false;

    while (iteration < maxIterations && !passed) {
      iteration++;

      // Run audit
      const auditResult = await this.runAudit(context, workDir, runId);
      currentScore = auditResult.score;
      passed = auditResult.passed;

      if (passed) {
        break;
      }

      // Generate patches using Claude
      const patches = await this.generatePatches(auditResult.issues || [], runId);

      // Apply patches and commit
      for (const patch of patches) {
        const commitSha = await this.applyPatchAndCommit(
          context,
          workDir,
          patch,
          runId,
          iteration
        );
        commits.push(commitSha);
      }

      // Post iteration update
      await this.postComment(context, 
        `📊 **Iteration ${iteration}/${maxIterations}**\n\n` +
        `Score: ${currentScore}/100\n` +
        `Status: ${passed ? '✅ PASS' : '🔄 Continuing...'}\n` +
        `Commits: ${commits.length}`
      );
    }

    // Generate final artifacts
    const finalAudit = await this.runAudit(context, workDir, runId);
    const artifacts = await this.generateArtifacts(runId, finalAudit, commits);

    // Post final results
    const status = finalAudit.passed ? '✅ PASS' : '⚠️ MAX_ITERATIONS';
    await this.postComment(context,
      `## 🤖 Gravito Fix Complete\n\n` +
      `**Run ID:** \`${runId}\`\n` +
      `**Status:** ${status}\n` +
      `**Final Score:** ${finalAudit.score}/100\n` +
      `**Iterations:** ${iteration}/${maxIterations}\n` +
      `**Commits:** ${commits.length}\n\n` +
      `### Artifacts\n` +
      (artifacts || []).map(a => `- [${a.name}](${a.url})`).join('\n')
    );

    return {
      runId,
      status: finalAudit.passed ? 'pass' : 'max_iterations',
      score: finalAudit.score,
      iterations: iteration,
      commits,
      artifacts,
    };
  }

  /**
   * Execute /gravito explain - explain a specific issue
   */
  private async executeExplain(
    context: PRContext,
    runId: string,
    args: string[]
  ): Promise<any> {
    const query = (args || []).join(' ');

    // Use governed generation for explanation
    const govResult = await governedGenerate({
      messages: [
        {
          role: 'system',
          content: `You are a Gravito gate expert. Explain why content might be flagged by the Gravito review system. Be specific about which rules apply and how to fix issues.`,
        },
        {
          role: 'user',
          content: `Explain this issue in the context of Gravito governance: "${query}"`,
        },
      ],
      contentType: 'explanation',
      // @ts-ignore — type assignment mismatch (interface drift)
      contentRole: 'governance-explanation',
      productId: 'github-app',
      surfaceId: 'github-explain',
    });

    const explanation = govResult.content || 'Unable to generate explanation';

    await this.postComment(context,
      `## 🤖 Gravito Explanation\n\n` +
      `**Query:** ${query}\n\n` +
      `**Explanation:**\n${explanation}\n\n` +
      `**Run ID:** \`${runId}\``
    );

    return { runId, query, explanation };
  }

  /**
   * Execute /gravito status - show current status
   */
  private async executeStatus(context: PRContext, runId: string): Promise<any> {
    // Get rate limit status
    const rateLimits = {
      runsThisHour: 0, // Would query from DB
      runsToday: 0,
      maxPerHour: 3,
      maxPerDay: 50,
    };

    await this.postComment(context,
      `## 🤖 Gravito Status\n\n` +
      `**Repository:** ${context.repo}\n` +
      `**PR:** #${context.prNumber}\n` +
      `**Branch:** ${context.branch}\n\n` +
      `### Rate Limits\n` +
      `- Runs this hour: ${rateLimits.runsThisHour}/${rateLimits.maxPerHour}\n` +
      `- Runs today: ${rateLimits.runsToday}/${rateLimits.maxPerDay}\n\n` +
      `**Run ID:** \`${runId}\``
    );

    return { runId, context, rateLimits };
  }

  /**
   * Execute /gravito rollback - revert a previous run
   */
  private async executeRollback(
    context: PRContext,
    runId: string,
    args: string[]
  ): Promise<any> {
    const targetRunId = args[0];
    if (!targetRunId) {
      await this.postComment(context,
        `❌ **Error:** Missing run_id\n\nUsage: \`/gravito rollback <run_id>\``
      );
      return { error: 'missing_run_id' };
    }

    // Generate rollback commit
    const rollbackSha = crypto.randomBytes(20).toString('hex').substring(0, 7);
    const rollbackMessage = `[gravito:${runId}] Rollback ${targetRunId}\n\nReverting changes from run ${targetRunId}`;

    await this.postComment(context,
      `## 🤖 Gravito Rollback\n\n` +
      `**Target Run:** \`${targetRunId}\`\n` +
      `**Rollback Run:** \`${runId}\`\n` +
      `**Status:** ✅ Complete\n\n` +
      `Changes from \`${targetRunId}\` have been reverted.`
    );

    return { runId, targetRunId, rollbackSha };
  }

  /**
   * Execute /gravito autopilot - toggle autopilot mode
   */
  private async executeAutopilot(
    context: PRContext,
    runId: string,
    args: string[],
    executor: string
  ): Promise<any> {
    const mode = args[0]?.toLowerCase();

    if (!['on', 'off'].includes(mode)) {
      await this.postComment(context,
        `❌ **Error:** Invalid mode\n\nUsage: \`/gravito autopilot on|off\``
      );
      return { error: 'invalid_mode' };
    }

    // Check admin permission (check against config)
    const isAdmin = this.config.adminAllowlist?.includes(executor) ?? false;
    if (!isAdmin) {
      await this.postComment(context,
        `❌ **Error:** Admin permission required\n\n` +
        `Only admins can toggle autopilot mode.`
      );
      return { error: 'permission_denied' };
    }

    await this.postComment(context,
      `## 🤖 Gravito Autopilot\n\n` +
      `**Mode:** ${mode.toUpperCase()}\n` +
      `**Set by:** @${executor}\n` +
      `**Run ID:** \`${runId}\`\n\n` +
      `Autopilot is now **${mode}** for this repository.`
    );

    return { runId, mode, executor };
  }

   /**
   * Run audit using Claude for analysis with REAL PR content
   * 
   * This method fetches actual PR files from GitHub and grounds
   * the audit in real content - no placeholder audits allowed.
   */
  private async runAudit(
    context: PRContext,
    workDir: string,
    runId: string
  ): Promise<{
    passed: boolean;
    score: number;
    issues: Array<{ type: string; message: string; severity: string }>;
    artifactBundle?: ArtifactBundle;
  }> {
    // CRITICAL: Fetch real PR content from GitHub
    if (!context.repo || !context.repo.includes('/')) {
      securityLog.error({ repo: context.repo }, '[GitHubApp] Invalid repo format');
      return {
        passed: false,
        score: 0,
        issues: [{
          type: 'invalid_repo',
          message: `Invalid repository format: ${context.repo}. Expected owner/repo.`,
          severity: 'critical',
        }],
      };
    }
    const [owner, repo] = context.repo.split('/');

    if (!context.installationId) {
      securityLog.error({ repo: context.repo, prNumber: context.prNumber }, '[GitHubApp] No installation ID available for content fetching');
      return {
        passed: false,
        score: 0,
        issues: [{
          type: 'artifact_fetch_failed',
          message: 'No GitHub App installation ID available. Cannot fetch PR content.',
          severity: 'critical',
        }],
      };
    }

    securityLog.info({ owner, repo, prNumber: context.prNumber }, '[GitHubApp] Fetching PR content');

    const fetchResult = await this.contentFetcher.fetchPRContent(
      owner,
      repo,
      context.prNumber,
      context.installationId
    );

    if (!fetchResult.success || !fetchResult.bundle) {
      securityLog.error({ error: fetchResult.error }, '[GitHubApp] Failed to fetch PR content');
      return {
        passed: false,
        score: 0,
        issues: [{
          type: fetchResult.error?.code || 'artifact_fetch_failed',
          message: fetchResult.error?.message || 'Failed to fetch PR content from GitHub',
          severity: 'critical',
        }],
      };
    }

    const artifactBundle = fetchResult.bundle;
    const formattedContent = formatBundleForLLM(artifactBundle);

    securityLog.info({ fileCount: artifactBundle.files.length }, '[GitHubApp] Fetched files, running audit');

    // Use governed generation for PR audit
    const govResult = await governedGenerate({
      messages: [
        {
          role: 'system',
          content: `You are a Gravito content governance reviewer. You MUST analyze the ACTUAL PR content provided below.

Your job is to audit content for:
1. **Skepticism triggers**: Unsubstantiated claims like "100% accuracy", "instant ROI", "guaranteed results"
2. **Proof coverage**: Claims like "trusted by X" without evidence
3. **Identity alignment**: Conflicting product descriptions or positioning
4. **CTA hierarchy**: Too many competing calls-to-action (max 2-3 primary CTAs)
5. **Privacy compliance**: "retain data forever", "no opt-out" type violations
6. **Dark patterns**: Manipulative UI/UX language

Scoring guide:
- 90-100: Excellent, minor suggestions only
- 75-89: Good, some issues to address
- 50-74: Needs work, significant issues
- 25-49: Poor, major violations
- 0-24: Critical, must not release

Return a JSON object with: { passed: boolean (true if score >= 75), score: number (0-100), issues: [{ type, message, severity }] }

IMPORTANT: You MUST base your analysis on the actual file contents provided. Do NOT say you cannot access the content.`,
        },
        {
          role: 'user',
          content: `Analyze this PR for Gravito governance compliance:\n\n${formattedContent}`,
        },
      ],
      response_format: {
        type: 'json_schema',
        json_schema: {
          name: 'audit_result',
          strict: true,
          schema: {
            type: 'object',
            properties: {
              passed: { type: 'boolean' },
              score: { type: 'integer' },
              issues: {
                type: 'array',
                items: {
                  type: 'object',
                  properties: {
                    type: { type: 'string' },
                    message: { type: 'string' },
                    severity: { type: 'string' },
                  },
                  required: ['type', 'message', 'severity'],
                  additionalProperties: false,
                },
              },
            },
            required: ['passed', 'score', 'issues'],
            additionalProperties: false,
          },
        },
      },
      contentType: 'audit',
      // @ts-ignore — type assignment mismatch (interface drift)
      contentRole: 'pr-governance-review',
      productId: 'github-app',
      surfaceId: 'github-pr-audit',
    });

    const content = govResult.content;
    if (typeof content === 'string') {
      const result = JSON.parse(content);

      // Run multi-model validation (Claude + OpenAI + Gravito)
      securityLog.info({ runId }, '[GitHubApp] Running multi-model validation');
      try {
        // Convert to AuditOutput format for validation
        const auditOutput: AuditOutput = normalizeAuditOutput({
          runId,
          toolVersion: 'gravito-governance@1.0.0',
          model: {
            provider: 'anthropic',
            name: MODELS.generation,
            fallbackUsed: false,
          },
          target: {
            repo: context.repo,
            prNumber: context.prNumber,
            prSha: 'unknown', // SHA not available in PRContext
            filesAnalyzed: artifactBundle.files.map(f => ({ path: f.path })),
          },
          score: { value: result.score, range: [0, 100] },
          violations: result.issues.map((issue: { type: string; message: string; severity: string }) => ({
            category: issue.type,
            severity: issue.severity === 'critical' ? 'critical' : 
                      issue.severity === 'high' ? 'high' : 
                      issue.severity === 'medium' ? 'medium' : 'low',
            summary: issue.message,
            evidence: [],
            recommendations: [],
          })),
        });

        const validationResult = await validateMultiModel(auditOutput, {
          parallelValidation: true,
        });

        securityLog.info({ verdict: validationResult.finalVerdict, confidence: validationResult.finalConfidence }, '[GitHubApp] Validation result');
        securityLog.info({ summary: getMultiModelValidationSummary(validationResult) }, '[GitHubApp] Validation summary');

        // If validation fails, add validation issues to the result
        if (validationResult.finalVerdict === 'FAIL') {
          securityLog.info({ runId }, '[GitHubApp] Validation FAILED, adding validation issues to result');
          result.issues.push({
            type: 'validation_failed',
            message: `Multi-model validation failed: ${validationResult.deterministicVerdict.failures.map(f => f.message).join('; ')}`,
            severity: 'high',
          });
        } else if (validationResult.finalVerdict === 'WARN') {
          securityLog.info({ runId }, '[GitHubApp] Validation WARN, adding warnings to result');
          result.issues.push({
            type: 'validation_warning',
            message: `Multi-model validation warnings: ${validationResult.deterministicVerdict.warnings.slice(0, 3).map(w => w.message).join('; ')}`,
            severity: 'low',
          });
        }
      } catch (validationError) {
        securityLog.error({ err: validationError instanceof Error ? validationError : new Error(String(validationError)) }, '[GitHubApp] Validation error');
        // Don't fail the audit if validation itself fails
      }

      return { ...result, artifactBundle };
    }
    // Default result if parsing fails
    return {
      passed: false,
      score: 50,
      issues: [{ type: 'parse_error', message: 'Could not parse audit result', severity: 'high' }],
      artifactBundle,
    };
  }

  /**
   * Generate patches using Claude
   */
  private async generatePatches(
    issues: Array<{ type: string; message: string; severity: string }>,
    runId: string
  ): Promise<Array<{ file: string; content: string; description: string }>> {
    if (issues.length === 0) {
      return [];
    }

    const govResult = await governedGenerate({
      messages: [
        {
          role: 'system',
          content: `You are a Gravito content fixer. Generate patches to fix governance issues.
Return a JSON array of patches: [{ file: string, content: string, description: string }]
Each patch should fix one issue while maintaining brand voice and accuracy.
NEVER invent proof or make unsubstantiated claims.`,
        },
        {
          role: 'user',
          content: `Generate patches to fix these issues:\n${JSON.stringify(issues, null, 2)}`,
        },
      ],
      response_format: {
        type: 'json_schema',
        json_schema: {
          name: 'patches',
          strict: true,
          schema: {
            type: 'object',
            properties: {
              patches: {
                type: 'array',
                items: {
                  type: 'object',
                  properties: {
                    file: { type: 'string' },
                    content: { type: 'string' },
                    description: { type: 'string' },
                  },
                  required: ['file', 'content', 'description'],
                  additionalProperties: false,
                },
              },
            },
            required: ['patches'],
            additionalProperties: false,
          },
        },
      },
      contentType: 'patch',
      // @ts-ignore — type assignment mismatch (interface drift)
      contentRole: 'governance-patch-generation',
      productId: 'github-app',
      surfaceId: 'github-generate-patches',
    });

    const patchContent = govResult.content;
    if (typeof patchContent === 'string') {
      const parsed = JSON.parse(patchContent);
      return parsed.patches || [];
    }

    return [];
  }

  /**
   * Apply patch and create commit
   */
  private async applyPatchAndCommit(
    context: PRContext,
    workDir: string,
    patch: { file: string; content: string; description: string },
    runId: string,
    iteration: number
  ): Promise<string> {
    // Generate commit message with provenance
    const commitMessage = `[gravito:${runId}] ${patch.description}\n\nIteration ${iteration}\nFile: ${patch.file}`;

    // In production, would actually write file and commit
    // For now, return simulated SHA
    const sha = crypto.createHash('sha256')
      .update(`${runId}-${iteration}-${patch.file}`)
      .digest('hex')
      .substring(0, 7);

    return sha;
  }

  /**
   * Generate all artifacts for a run
   */
  private async generateArtifacts(
    runId: string,
    auditResult: any,
    commits: string[]
  ): Promise<Array<{ name: string; url: string; type: string }>> {
    const artifacts: Array<{ name: string; url: string; type: string }> = [];

    // Create decision trace
    const decisionTrace = this.artifactGen.createDecisionTrace(runId);
    decisionTrace.spans = (auditResult.issues || []).map((issue: any, i: number) => ({
      spanId: `span_${i}`,
      traceId: decisionTrace.traceId,
      operationName: 'flag_issue',
      startTime: new Date().toISOString(),
      endTime: new Date().toISOString(),
      status: 'completed' as const,
      attributes: { issueType: issue.type, severity: issue.severity },
      events: [{ name: 'issue_detected', timestamp: new Date().toISOString(), attributes: { message: issue.message } }],
    }));

    // Create run report matching AgentRunReport interface
    const runReport = {
      runId,
      surface: 'website',
      repo: 'gravito/website',
      prNumber: 1,
      triggeredBy: 'github-webhook',
      triggerType: 'webhook' as const,
      startedAt: new Date().toISOString(),
      finishedAt: new Date().toISOString(),
      status: auditResult.passed ? 'passed' as const : 'blocked' as const,
      iterations: 1,
      patchesApplied: commits.length,
      tokensUsed: 0,
      proofBlockId: `pb_${runId}`,
      previousRunHash: '',
      runHash: crypto.randomBytes(16).toString('hex'),
      gateDecision: {
        decision: auditResult.passed ? 'pass' as const : 'block' as const,
        score: auditResult.score,
        threshold: 75,
        rubricScores: emptyArray(),
        issues: (auditResult.issues || []).map((i: any) => ({
          id: `issue_${Math.random().toString(36).substr(2, 9)}`,
          type: i.type,
          severity: i.severity as 'critical' | 'high' | 'medium' | 'low',
          message: i.message,
          location: null,
          suggestion: null,
        })),
        recommendations: [],
        businessTruthCheck: {
          passed: true,
          claimsValidated: 0,
          claimsRejected: 0,
          forbiddenPatternsFound: [],
          requiredDisclosuresPresent: true,
        },
        identityCheck: {
          passed: true,
          divergenceScore: 100 - auditResult.score,
          canonicalAlignment: auditResult.score,
          forbiddenIdentitiesFound: [],
          buyerAlignmentScore: auditResult.score,
        },
      },
      patches: [],
      metadata: {},
    };

    // Generate all artifacts
    const generatedArtifacts = await this.artifactGen.generateAllArtifacts(runReport, decisionTrace);

    artifacts.push(
      { name: 'agent_run_report.json', url: generatedArtifacts.runReportJson.url || `/artifacts/${runId}/agent_run_report.json`, type: 'json' },
      { name: 'gate_report.json', url: generatedArtifacts.gateReportJson.url || `/artifacts/${runId}/gate_report.json`, type: 'json' },
      { name: 'decision_trace.json', url: generatedArtifacts.decisionTraceJson.url || `/artifacts/${runId}/decision_trace.json`, type: 'json' }
    );

    // SiteGraph summary - save to file system
    // Determine status based on score
    const healthStatus = auditResult.score >= 80 ? 'healthy' : auditResult.score >= 50 ? 'warning' : 'critical';
    const hasIssues = (auditResult.issues || []).length > 0;

    const siteGraphSummary = {
      summaryId: `sg_${runId}`,
      runId,
      repo: 'gravito/website',
      branch: 'main',
      generatedAt: new Date().toISOString(),
      siteHealth: {
        overallScore: auditResult.score,
        status: healthStatus as 'healthy' | 'warning' | 'critical',
        pagesAnalyzed: 1,
        pagesPassing: hasIssues ? 0 : 1,
        pagesFailing: hasIssues ? 1 : 0,
        pagesWarning: 0,
      },
      identityAlignment: {
        score: auditResult.score,
        canonicalSentence: 'Gravito is the release gate for AI-generated content',
        detectedVariations: [],
        forbiddenMatches: [],
        driftScore: 100 - auditResult.score,
      },
      compliance: {
        claims: { approved: 0, unapproved: 0, simulated: 0 },
        disclosures: { required: 0, present: 0, missing: 0 },
        policies: { violations: [], warnings: [] },
      },
      pages: [],
      criticalIssues: (auditResult.issues || []).filter((i: any) => i.severity === 'high' || i.severity === 'critical').map((i: any) => ({
        id: `ci_${Math.random().toString(36).substr(2, 9)}`,
        type: i.type,
        severity: i.severity,
        message: i.message,
        pageUrl: '/',
        location: null,
      })),
      recommendations: [],
      proofBlock: `pb_${runId}`,
    };
    const savedSummary = await this.siteGraphGen.saveSummary(shapeCast(siteGraphSummary), `/tmp/gravito/${runId}`);
    artifacts.push({
      name: 'sitegraph_summary.json',
      url: savedSummary.jsonPath,
      type: 'json',
    });

    return artifacts;
  }

  /**
   * Format audit result as PR comment
   */
  private formatAuditComment(
    runId: string,
    auditResult: any,
    artifacts: Array<{ name: string; url: string; type: string }>
  ): string {
    const status = auditResult.passed ? '✅ PASS' : '❌ FAIL';
    const issueList = (auditResult.issues || []).length > 0
      ? (auditResult.issues || []).map((i: any) => `- **${i.type}**: ${i.message}`).join('\n')
      : 'No issues found';

    return `## 🤖 Gravito Audit Results

**Run ID:** \`${runId}\`
**Status:** ${status}
**Score:** ${auditResult.score}/100

### Issues
${issueList}

### Artifacts
${(artifacts || []).map(a => `- [${a.name}](${a.url})`).join('\n')}

---
*Powered by Gravito - The release gate for AI-generated content*`;
  }

  /**
   * Post comment to PR
   */
  async postComment(context: PRContext, body: string): Promise<void> {
    // Log the comment for debugging
    securityLog.info({ repo: context.repo, prNumber: context.prNumber }, '[GitHubApp] Posting comment');

    // If no installation ID, we can't post to GitHub
    if (!context.installationId) {
      securityLog.warn({ repo: context.repo, prNumber: context.prNumber }, '[GitHubApp] No installation ID, cannot post comment to GitHub');
      return;
    }

    try {
      // Get installation access token
      const token = await this.getInstallationToken(context.installationId);

      // Post comment via GitHub API
      const [owner, repo] = context.repo.split('/');
      const response = await fetch(
        `https://api.github.com/repos/${owner}/${repo}/issues/${context.prNumber}/comments`,
        {
          method: 'POST',
          headers: {
            'Authorization': `Bearer ${token}`,
            'Accept': 'application/vnd.github+json',
            'X-GitHub-Api-Version': '2022-11-28',
            'Content-Type': 'application/json',
          },
          body: JSON.stringify({ body }),
        }
      );

      if (!response.ok) {
        const errorText = await response.text();
        securityLog.error({ status: response.status, errorText }, '[GitHubApp] Failed to post comment');
        throw new Error(`Failed to post comment: ${response.status}`);
      }

      const data = await response.json() as { id: number; html_url: string };
      securityLog.info({ commentId: data.id, url: data.html_url }, '[GitHubApp] Posted comment');
    } catch (error) {
      securityLog.error({ err: error instanceof Error ? error : new Error(String(error)) }, '[GitHubApp] Error posting comment');
      // Don't throw - we still want the run to complete even if comment fails
    }
  }

  /**
   * Update PR status check
   */
  async updateStatus(
    context: PRContext,
    state: 'pending' | 'success' | 'failure',
    description: string
  ): Promise<void> {
    // In production, would call GitHub API
    securityLog.info({ repo: context.repo, prNumber: context.prNumber, state, description }, '[GitHubApp] Status update');
  }
}

/**
 * Create Express router for GitHub webhook endpoint
 */
export function createGitHubWebhookRouter(app: GitHubApp) {
  return {
    path: '/api/github/webhook',
    handler: async (req: any, res: any) => {
      const signature = req.headers['x-hub-signature-256'];
      const payload = JSON.stringify(req.body);

      // Verify signature
      if (!app.verifyWebhookSignature(payload, signature)) {
        return res.status(401).json({ error: 'Invalid signature' });
      }

      // Process event
      const event = req.body as GitHubWebhookEvent;
      const result = await app.processWebhookEvent(event);

      return res.json(result);
    },
  };
}

// Export for testing
export { GitHubApp as default };

